using System.Text.Json.Nodes;
using System.Security.Cryptography;
using System.Text;
namespace AetherGrid.Server;
// Provider-neutral reconciliation boundary. No network execution or financial custody.
public static class Providers
{
 public static void Map(WebApplication app,Store store,IConfiguration config){
 app.MapPost("/api/integrations/intents",(HttpContext c,JsonObject p)=>{Security.Review(c,p);return store.Write(tx=>{var key=p.S("idempotency_key");J.Require(key.Length is >=12 and <=120,"Idempotency key required");var lot=p.S("batch_id");var s=tx.Need("settlement",lot);var kind=p.S("kind");J.Require(kind is "payment" or "insurance","Unknown intent kind");var amount=(long)Math.Round(s.N(kind=="payment"?"farmer_total_payout_inr":"insurance_payout_inr")*100,MidpointRounding.ToEven);var old=tx.Get("intent",key);if(old is not null){J.Require(old.S("batch_id")==lot&&old.S("kind")==kind,"Idempotency conflict",409);return old;}J.Require(!tx.All("intent").Any(x=>x.S("batch_id")==lot&&x.S("kind")==kind),"Duplicate obligation",409);var intent=new JsonObject{["id"]=key,["batch_id"]=lot,["kind"]=kind,["amount_paise"]=amount,["currency"]="INR",["state"]="created",["adapter"]="sandbox-contract",["created_at"]=J.Now(),["financial_execution"]=false};tx.Put("intent",key,intent);tx.Event("intent_created",lot,intent.Copy());return intent;});});
 app.MapGet("/api/integrations/intents",(HttpContext c)=>{Security.Operator(c);return store.Read(tx=>tx.All("intent"));});
 app.MapPost("/api/integrations/intents/{id}/dispatch",(HttpContext c,string id,JsonObject p)=>{Security.Review(c,p);return store.Write(tx=>{var x=tx.Need("intent",id);J.Require(x.S("adapter")=="sandbox-contract","Unsupported adapter");if(x.S("state")=="created"){x["state"]="pending";x["provider_reference"]="SANDBOX-"+Security.Hash(id)[..20];x["dispatched_at"]=J.Now();tx.Put("intent",id,x);tx.Event("intent_dispatched",x.S("batch_id"),x.Copy());}return x;});});
 app.MapPost("/api/integrations/intents/{id}/callback",(HttpContext c,string id,JsonObject p)=>{Security.Operator(c);var secret=config["AETHER_CALLBACK_SECRET"];J.Require(secret?.Length>=32,"Sandbox callback secret not configured",503);var message=id+"|"+p.S("event_id")+"|"+p.S("provider_reference")+"|"+p.S("state")+"|"+p.N("amount_paise").ToString("0",System.Globalization.CultureInfo.InvariantCulture)+"|"+p.S("currency")+"|"+p.N("timestamp").ToString("0",System.Globalization.CultureInfo.InvariantCulture);var mac=Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(secret!),Encoding.UTF8.GetBytes(message))).ToLowerInvariant();J.Require(Security.Same(mac,c.Request.Headers["X-Callback-Signature"].ToString()),"Invalid callback signature",403);J.Require(Math.Abs(J.Epoch()-p.N("timestamp"))<=300&&p.S("event_id").Length>=8,"Invalid callback envelope");return store.Write(tx=>{var x=tx.Need("intent",id);var digest=Security.Hash(message);var prior=tx.Get("callback",p.S("event_id"));if(prior is not null){J.Require(prior.S("digest")==digest,"Event collision",409);return x;}J.Require(x.S("state")=="pending","Callback cannot change terminal/unsubmitted intent",409);J.Require(p.S("state") is "succeeded" or "failed"&&p.N("amount_paise")==x.N("amount_paise")&&p.S("currency")=="INR"&&p.S("provider_reference")==x.S("provider_reference"),"Callback obligation mismatch",409);x["state"]=p.S("state");x["reconciled_at"]=J.Now();tx.Put("intent",id,x);tx.Put("callback",p.S("event_id"),new JsonObject{["digest"]=digest});tx.Event("intent_reconciled",x.S("batch_id"),x.Copy());return x;});});
 }
}
